-- sort_order 301: 日本の職人文化  answer=2  (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本の職人文化', E'日本には「職人」と呼ばれる、特定の技術や技能を長年にわたって磨き続ける人々がいる。陶芸・漆工芸・刃物製造・組子細工など、各地の伝統工芸においてその精神は受け継がれてきた。\n職人の世界では、師匠のもとで長い年月をかけて技を習得する「徒弟制度」が伝統的に重視されてきた。数年から十数年をかけて基礎を叩き込まれ、一人前と認められるまで独立できないのが慣例だ。この過程で身につくのは技術だけでなく、ものに向き合う姿勢や集中力、仕事への誇りでもある。\nしかし近年、後継者不足が深刻な問題となっている。若い世代が職人の道を選ばなくなったこと、また消費者がより安価な工業製品を選ぶ傾向にあることが原因として挙げられる。伝統技術の保存と継承のため、各地で体験教室や後継者育成プログラムが開かれているが、根本的な解決には至っていない。', 'essay', 'N2', 330, '[]'::jsonb,
  '{"question":"本文で職人の徒弟制度について述べられていることとして正しいものはどれか。","options":["師匠に認められれば入門後すぐに独立できる。","徒弟制度では技術だけが伝わり、仕事への姿勢は個人が学ぶ。","長い年月をかけて技を習得し、一人前と認められて初めて独立できる。","現在は法律で徒弟制度が禁止されている。"],"answer":2}'::jsonb, 301
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本の職人文化');

-- sort_order 302: 社員研修のご案内  answer=0  (notice)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '社員研修のご案内', E'社員各位\n\n来月より、全社員を対象とした情報セキュリティ研修を実施いたします。近年、フィッシングメールや不正アクセスによる情報漏洩事故が業界全体で増加していることを受け、今年度から義務化することといたしました。\n研修はオンライン形式で行い、所要時間は約2時間です。受講期間は来月1日から末日まででございます。受講後は確認テストがございますので、必ず最後まで完了してください。テストに合格しない場合は、再受講が必要となります。\n研修用URLは別途メールにてご案内いたします。受講状況は人事部にて管理しており、期限までに受講が確認できない社員については、上長へ報告いたします。業務でお忙しいところ恐縮ですが、情報セキュリティはわが社全員で取り組むべき重要課題です。ご協力のほど、よろしくお願いいたします。\n\n人事部', 'notice', 'N2', 295, '[]'::jsonb,
  '{"question":"この案内に書かれている研修について正しいものはどれか。","options":["研修は今年度から全社員に義務づけられており、期限内に受講しないと上長に報告される。","研修は対面形式で行われ、会議室への出席が必要である。","確認テストに合格できなかった場合、そのまま修了と認められる。","研修のURLは当日会場で配布される。"],"answer":0}'::jsonb, 302
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='社員研修のご案内');

-- sort_order 303: 日本のコンビニエンスストア  answer=1  (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本のコンビニエンスストア', E'日本のコンビニエンスストアは、単なる食料品店を超えた「生活インフラ」としての役割を担っている。全国に約5万5千店舗が存在し、24時間365日営業しているものがほとんどだ。\nコンビニでできることは多岐にわたる。弁当・惣菜・スイーツなどの食品購入はもちろん、公共料金の支払い・ATMの利用・各種チケットの発券・荷物の受け取りなど、生活に必要なサービスが一か所で完結する。また、コピー機やFAXも完備しており、行政書類の印刷ができる店舗も増えている。\n一方で課題もある。24時間営業を維持するための人手不足は深刻で、オーナーが長時間労働を余儀なくされるケースも多い。また、廃棄食品の削減という観点から、一部のチェーンでは深夜の営業時間を短縮する試みも始まっている。便利さと持続可能性のバランスをどうとるかが、今後の課題となっている。', 'article', 'N2', 330, '[]'::jsonb,
  '{"question":"本文でコンビニエンスストアの課題として挙げられているものはどれか。","options":["商品の品揃えが少なく、購入できるものが限られていること","24時間営業を維持するための人手不足とオーナーの長時間労働","公共料金の支払いができる店舗が少ないこと","ATMの手数料が高く利用者が減少していること"],"answer":1}'::jsonb, 303
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本のコンビニエンスストア');

