-- sort_order 305: 日本の農業の変化  answer=0  (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本の農業の変化', E'日本の農業は、高齢化と担い手不足という深刻な問題に直面している。農業従事者の平均年齢は67歳を超えており、若い後継者が育たないまま、耕作放棄地が増え続けている。\nこうした状況を打開するため、農業へのIT・AI技術の導入が進んでいる。ドローンによる農薬散布や、センサーを使った土壌管理、AIによる収穫時期の予測など、いわゆる「スマート農業」が各地で実用化されつつある。これにより、少ない人手で大規模な農地を管理できるようになると期待されている。\n一方、都市部の若者が農業に関心を持つ「農業女子」「半農半X」といった新しいライフスタイルも注目を集めている。農業と別の仕事を組み合わせる生き方や、有機農業・直売所を活用したビジネスモデルが、農業の担い手を増やす可能性として期待されている。技術革新と新たな就農者の確保の両輪で、日本農業の持続可能性を高めることが急務となっている。', 'article', 'N2', 335, '[]'::jsonb,
  '{"question":"本文でスマート農業として挙げられているものはどれか。","options":["ドローンによる農薬散布・センサーを使った土壌管理・AIによる収穫時期の予測","農業女子と呼ばれる女性農家が増加していること","耕作放棄地を宅地として転用すること","直売所を活用したビジネスモデルの普及"],"answer":0}'::jsonb, 305
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本の農業の変化');

