-- sort_order 307: 読書の効用  answer=2  (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '読書の効用', E'デジタルメディアが普及した現代においても、読書は依然として重要な知的活動の一つである。本を読むことには、語彙力や読解力の向上・想像力の豊かさ・論理的思考力の涵養など、さまざまな効用が認められている。\nとくに「深い読書」とも呼ばれる長編小説や評論の読書は、他者の視点や感情を追体験することで共感力を育てるとされる。スクロールしながら断片的に情報を消費するSNSの閲覧とは異なり、本を読む行為は集中力を維持しながら長い文章の構造を理解する訓練になる。\nしかし、読書人口の減少は否定しがたい現実だ。出版科学研究所の調査によると、書籍の販売額は2000年代以降、長期的な減少傾向にある。電子書籍やオーディオブックの普及が新たな読者層を開拓しているという見方もあるが、いずれにせよ「何を読むか」よりも「いかに深く読むか」が、情報過多の時代においてより重要な問いとなっている。', 'essay', 'N2', 335, '[]'::jsonb,
  '{"question":"本文で「深い読書」の効用として述べられているものはどれか。","options":["インターネット検索を速くする能力が身につく","断片的な情報を素早く処理できるようになる","他者の視点や感情を追体験することで共感力が育まれる","電子書籍やオーディオブックの利用が促進される"],"answer":2}'::jsonb, 307
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='読書の効用');

-- sort_order 308: 日本のファッション産業  answer=3  (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本のファッション産業', E'日本のファッション産業は、世界的に見ても独自の発展を遂げてきた。原宿や渋谷から発信される若者文化・ストリートファッションは「ハラジュク」として世界に広まり、日本のポップカルチャーの一部として認知されている。\n一方、「ユニクロ」や「無印良品」に代表されるシンプルで高品質な日本のベーシックブランドも、海外で高い評価を得ている。過度な装飾を排した機能的なデザインと、品質へのこだわりが支持される理由だ。\nしかし近年、「ファストファッション」の普及により、安価で大量生産された衣類の消費が増え、廃棄される衣料品の量も急増している。日本国内では年間約50万トンの衣類が廃棄されているとされ、環境負荷の観点から問題視されている。こうした背景から、長く着られる品質の高い服を選ぶ「スローファッション」や、古着の再利用を促す「アップサイクル」への関心も高まっている。', 'article', 'N2', 330, '[]'::jsonb,
  '{"question":"本文でファストファッションの問題として述べられているものはどれか。","options":["日本のブランドが海外で人気を失っていること","原宿や渋谷のファッションが世界に広まったこと","無印良品の製品が国内で売れなくなっていること","廃棄される衣料品の量が急増し、環境負荷が高まっていること"],"answer":3}'::jsonb, 308
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本のファッション産業');

-- sort_order 309: 公共交通機関のマナー  answer=0  (essay)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '公共交通機関のマナー', E'日本の鉄道やバスは、時刻通りの運行と車内の静粛さで世界的に知られている。乗客が自発的にルールを守る文化が、快適な公共交通環境を作り出していると言える。\n車内では優先席の譲り合い・通話の自粛・荷物の置き方など、さまざまなマナーが求められる。これらは法律で義務づけられているわけではないが、「周囲に迷惑をかけない」という日本社会の規範意識に基づいている。外国人旅行者からは「なぜ皆がそんなに静かにしているのか」と驚かれることも多い。\nしかし時代とともにマナーの内容も変化している。かつては車内での化粧が問題視されていたが、今日ではスマートフォンの操作やイヤホンから漏れる音楽が新たな摩擦の原因となっている。マナーとは時代の変化に合わせて更新されていくものであり、「みんなが気持ちよく利用できる空間を作る」という本質的な目的は変わらない。', 'essay', 'N2', 325, '[]'::jsonb,
  '{"question":"本文で日本の公共交通機関のマナーについて述べられていることとして正しいものはどれか。","options":["マナーは法律で義務づけられているわけではなく、「周囲に迷惑をかけない」という規範意識に基づいている。","車内での通話は法律で禁止されている。","外国人旅行者は日本の電車が静かすぎると批判している。","スマートフォンの使用は現在すべての路線で禁止されている。"],"answer":0}'::jsonb, 309
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='公共交通機関のマナー');

-- sort_order 310: キャッシュレス決済の普及  answer=1  (article)
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'キャッシュレス決済の普及', E'日本では長らく現金志向が強く、クレジットカードや電子マネーによるキャッシュレス決済の普及率は他の先進国と比べて低い水準にあった。しかし2019年のポイント還元施策を機に、スマートフォンを使ったQRコード決済が急速に広まり、状況は大きく変わった。\nキャッシュレス決済のメリットは多い。支払いがスムーズで財布の中の小銭を管理する手間が省け、家計の支出を自動的に記録できる。店舗側にとっても、現金の取り扱いにかかる手間やコストを削減できるという利点がある。\nいっぽう、課題もある。高齢者を中心に、スマートフォンの操作に不慣れなためキャッシュレス決済を利用できない人も少なくない。また、大規模なシステム障害が発生した際に決済ができなくなるリスクや、個人情報の管理・セキュリティ面の不安を指摘する声もある。現金とキャッシュレスを適切に使い分けられる環境整備が、今後も引き続き求められる。', 'article', 'N2', 335, '[]'::jsonb,
  '{"question":"本文でキャッシュレス決済の普及が進むきっかけとして述べられているものはどれか。","options":["大手コンビニチェーンが現金の取り扱いを廃止したこと","2019年のポイント還元施策によりQRコード決済が急速に広まったこと","高齢者向けのスマートフォン教室が全国で開催されたこと","政府が現金の流通を法律で制限したこと"],"answer":1}'::jsonb, 310
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='キャッシュレス決済の普及');
